E2M, E2V, E2C, E2K = "results/extE2_metrics_all.csv", "results/extE2_vs_ridge.csv", "results/extE2_calibration.csv", "results/extE2_sklearn_check.csv"
SCRIPT.update({E2M: "src/ext_E2_bayes_ridge.py (src/extlib.py)", E2V: "src/ext_E2_bayes_ridge.py (src/extlib.py)", E2C: "src/ext_E2_bayes_ridge.py", E2K: "src/ext_E2_bayes_ridge.py"})
e = []; a = e.append
Q_LOPO, Q_X = "sample in ['pooled', 'long']", "sample == 'cross2long'"
a("### 8.2 E2: Bayesian ridge regression from scratch\n")
a("Math note: `docs/math/E2_bayesian_ridge.md`. Gaussian prior on the weights, exact Gaussian posterior (mean m, covariance S), predictive mean and variance for a new session, noise precision beta and prior precision alpha chosen by **evidence maximisation inside each training fold** (no inner CV). Same leave-one-woman-out folds and same women as the Phase 4 ridge, which is the comparison (its lambda is chosen by nested CV).\n")
nfin = agg(E2K, "alpha_finite", None, "count", "{:.0f}", label="E2 parity configs with finite alpha"); ninf = agg(E2K, "not alpha_finite", None, "count", "{:.0f}", label="E2 parity configs with alpha to infinity")
claim(float(df(E2K).max_abs_diff_weights.max()) < 1e-8 and float(df(E2K).rel_diff_beta.max()) < 1e-8, "Bayesian ridge matches scikit-learn")
claim(int(agg(E2C, "", "n_nonconverged_folds", "sum", "{:.0f}")) == 0, "all evidence fixed points converged")
a(f"**Check against scikit-learn.** `BayesianRidge` with all Gamma hyper-priors set to zero (pure evidence maximisation) on the full samples ({agg(E2K, '', None, 'count', '{:.0f}', label='E2 parity configs')} configurations: pooled {nn('pooled')} and longitudinal {nn('long')} x 3 targets x 5 sets): largest difference in the posterior-mean weights {agg(E2K, '', 'max_abs_diff_weights', 'max', '{:.1e}', label='E2 max |dw|')}, in the noise precision {agg(E2K, '', 'rel_diff_beta', 'max', '{:.1e}', label='E2 max rel diff beta')} (relative), in the prior precision {agg(E2K, 'alpha_finite', 'rel_diff_alpha', 'max', '{:.1e}', label='E2 max rel diff alpha (finite)')} (relative; {nfin} configurations with a finite alpha). In {ninf} configurations the evidence prefers no signal (alpha grows without bound, weights shrunk to zero, alpha not identifiable); the weights still agree. The evidence iterations converged in all {agg(E2C, '', 'n_nonconverged_folds', 'sum', '{:.0f}', label='E2 non-converged folds') and calc('E2 number of folds', float(df('results/extE2_oof.csv').groupby(['sample', 'target', 'fset']).VPN.nunique().sum()), '{:.0f}', 'results/extE2_oof.csv', 'sum over configurations of the number of held-out women (folds)')} folds (non-converged: {agg(E2C, '', 'n_nonconverged_folds', 'sum', '{:.0f}', label='E2 non-converged folds')}).\n")
a("**Out-of-fold results.** Columns: R2 versus the training-mean baseline [95% CI over women] for the Bayesian ridge and for the Phase 4 ridge; change in RMSE (Bayes minus ridge, negative = Bayes better); calibration of the predictive variance: mean squared standardised error z^2 (target 1; above 1 = over-confident) and the change in mean negative log predictive density (nats per session) relative to a Gaussian with the training mean and variance (negative = better).\n")
for s_ in ["pooled", "long", "cross2long"]:
    a(f"**{SMP[s_].capitalize()} sample** " + (f"(training {nn('cross')}; test {nn('long')})." if s_ == "cross2long" else f"({nn(s_)}).") + "\n")
    a("| Target | Set | Bayesian ridge R2_oos | Ridge R2_oos | RMSE change | mean z^2 | NLPD change vs constant Gaussian |\n|---|---|---|---|---|---|---|")
    for t in TS:
        for f_ in ["A", "B", "C", "D2", "D"]:
            w = dict(sample=s_, target=t, fset=f_)
            a(f"| {TN[t]} | {f_} | {ci(E2M, dict(sample=s_, target=t, model='bayes_ridge', fset=f_), 'R2_oos', '{:+.3f}', label=f'E2 bayes {s_} {t} {f_}')} | {ci(E2M, dict(sample=s_, target=t, model='ridge', fset=f_), 'R2_oos', '{:+.3f}', label=f'E2 ridge {s_} {t} {f_}')} | {ci(E2V, dict(sample=s_, target=t, first=f'bayes_ridge/{f_}', second=f'ridge/{f_}', metric='RMSE'), 'delta', '{:+.3f}', lo='lo', hi='hi', label=f'E2 dRMSE {s_} {t} {f_}')} | {ci(E2C, w, 'mean_z2', '{:.2f}', lo='mean_z2_lo', hi='mean_z2_hi', label=f'E2 z2 {s_} {t} {f_}')} | {ci(E2C, w, 'd_nlpd_vs_const_gauss', '{:+.3f}', lo='d_nlpd_lo', hi='d_nlpd_hi', label=f'E2 dNLPD {s_} {t} {f_}')} |")
    a("")
table("T-E2", "Bayesian ridge vs ridge, calibration", f"{E2M}, {E2V}, {E2C}", "src/ext_E2_bayes_ridge.py")
rv = df(E2V); rv = rv[rv.metric == "RMSE"]; nv = len(rv); nsig = int(rv.excludes_0.sum()); nb = int(((rv.delta < 0) & rv.excludes_0).sum()); nw_ = int(((rv.delta > 0) & rv.excludes_0).sum())
lo_s = df(E2C)[df(E2C)["sample"].isin(["pooled", "long"])]; cr_ = df(E2C)[df(E2C)["sample"] == "cross2long"]; inc = int(((lo_s.mean_z2_lo <= 1) & (lo_s.mean_z2_hi >= 1)).sum())
a(f"**Accuracy: Bayesian ridge and ridge are practically the same.** Across the {calc('E2 comparisons', nv, '{:.0f}', E2V, 'number of RMSE comparisons Bayes vs ridge')} comparisons the median RMSE change is {calc('E2 median dRMSE', float(rv.delta.median()), '{:+.4f}', E2V, 'median delta, metric RMSE')} and the largest absolute change {calc('E2 max abs dRMSE', float(rv.delta.abs().max()), '{:.3f}', E2V, 'max |delta|, metric RMSE')}; the interval excludes 0 in {calc('E2 n significant', nsig, '{:.0f}', E2V, 'excludes_0 count')} ({calc('E2 n Bayes better', nb, '{:.0f}', E2V, 'delta<0 and excludes_0')} in favour of the Bayesian ridge, {calc('E2 n ridge better', nw_, '{:.0f}', E2V, 'delta>0 and excludes_0')} in favour of ridge), differences that are tiny in size. This is expected: both give the same functional form, only the way the shrinkage is chosen differs (evidence versus cross-validation). As an example of how the two ways of choosing the shrinkage differ, in the pooled DRSP model with set D the evidence chose weaker shrinkage than cross-validation (equivalent lambda {val(E2C, dict(sample='pooled', target='drsp_psych', fset='D'), 'median_lambda_equiv', '{:.3f}', label='E2 median lambda equiv pooled drsp D')} versus {val(E2C, dict(sample='pooled', target='drsp_psych', fset='D'), 'median_lambda_ridge_cv', '{:.3f}', label='E2 median lambda CV pooled drsp D')}, median over folds) and, when there is nothing to learn (e.g. anxiety from phase and hormones), shrinks the weights to zero: {agg(E2C, 'median_eff_params < 0.01', None, 'count', '{:.0f}', label='E2 configs with no effective parameters')} of {agg(E2C, '', None, 'count', '{:.0f}', label='E2 configurations')} configurations have a median effective number of parameters below {calc('E2 gamma threshold', 0.01, '{:.2f}', 'definition', 'threshold used in the query')}. Choosing the shrinkage by the evidence needs no inner cross-validation loop.\n")
a(f"**Calibration of the predictive variance.** Within the leave-one-woman-out samples (pooled and longitudinal; {agg(E2C, Q_LOPO, None, 'count', '{:.0f}', label='E2 LOPO configs')} configurations) the mean z^2 lies between {agg(E2C, Q_LOPO, 'mean_z2', 'min', '{:.2f}', label='E2 min mean z2 LOPO')} and {agg(E2C, Q_LOPO, 'mean_z2', 'max', '{:.2f}', label='E2 max mean z2 LOPO')}, and the 95% interval contains 1 in {calc('E2 CIs containing 1', inc, '{:.0f}', E2C, 'mean_z2_lo <= 1 <= mean_z2_hi, LOPO samples')} of them: the predictive variance is roughly calibrated on average. It is, however, almost constant across sessions (ratio of the largest to the smallest predictive sd within a configuration at most {calc('E2 max sd ratio', float((df(E2C).sd_pred_max / df(E2C).sd_pred_min).max()), '{:.2f}', E2C, 'max of sd_pred_max/sd_pred_min')}), because the noise term dominates and the weights are uncertain only in small ways, so it carries little session-specific information. The log predictive density improves over a constant Gaussian only for the questionnaire-based sets (pooled, DRSP, set D: {ci(E2C, dict(sample='pooled', target='drsp_psych', fset='D'), 'd_nlpd_vs_const_gauss', '{:+.3f}', lo='d_nlpd_lo', hi='d_nlpd_hi', label='E2 dNLPD pooled drsp D')} nats per session); for phase and hormone sets it is {ci(E2C, dict(sample='pooled', target='drsp_psych', fset='C'), 'd_nlpd_vs_const_gauss', '{:+.3f}', lo='d_nlpd_lo', hi='d_nlpd_hi', label='E2 dNLPD pooled drsp C')} (set C, DRSP), i.e. no gain. **When the test women come from a different study sample (training on the {n_wom('cross')} cross-sectional women, test on the {n_wom('long')} longitudinal women) the model is over-confident**: mean z^2 between {agg(E2C, Q_X, 'mean_z2', 'min', '{:.2f}', label='E2 min mean z2 cross2long')} and {agg(E2C, Q_X, 'mean_z2', 'max', '{:.2f}', label='E2 max mean z2 cross2long')}; the noise variance learned on one group underestimates the variability in the other: the standard deviation of DRSP psychological symptoms is {calc('SD DRSP cross rows', float(Cs.DRSP_psychisch.std()), '{:.1f}', SRC, 'std of DRSP_psychisch, cross-sectional rows')} in the training sample but {calc('SD DRSP long rows', float(Ls.DRSP_psychisch.std()), '{:.1f}', SRC, 'std of DRSP_psychisch, longitudinal rows')} in the test sample (n = {nn('cross')} and {nn('long')}). This is a distribution-shift effect: the prior and the evidence cannot know about spread that the training sample does not contain. Coverage of the resulting intervals is examined in E4.\n")
a("**Limits.** Rows are treated as independent although sessions of one woman are correlated, so the uncertainty about the *woman-level* level is folded into the noise; the intercept is fixed at the training mean; the predictive distribution is Gaussian by assumption.\n")
